def rot13(texto: str) -> str:
    if not isinstance(texto, str):
        raise TypeError("O argumento deve ser uma string.")
    resultado = []
    for c in texto:
        if 'A' <= c <= 'Z':
            base = ord('A')
            resultado.append(chr((ord(c) - base + 13) % 26 + base))
        elif 'a' <= c <= 'z':
            base = ord('a')
            resultado.append(chr((ord(c) - base + 13) % 26 + base))
        else:
            resultado.append(c)
    return ''.join(resultado)

def calcular_pontuacao_base(tempo_segundos: int, erros: int) -> int:
    if not isinstance(tempo_segundos, int) or not isinstance(erros, int):
        raise ValueError("tempo_segundos e erros devem ser inteiros")
    if tempo_segundos < 0 or erros < 0:
        raise ValueError("tempo_segundos e erros não podem ser negativos")
    return max(0, 1000 - tempo_segundos * 5 - erros * 50)


def calcular_pontuacao_final(pontuacao_base: int, multiplicador: float) -> int:
    if not isinstance(pontuacao_base, int):
        raise ValueError("pontuacao_base deve ser inteiro")
    if pontuacao_base < 0:
        raise ValueError("pontuacao_base não pode ser negativo")
    if not isinstance(multiplicador, (int, float)):
        raise ValueError("multiplicador deve ser número")
    if multiplicador < 0.5 or multiplicador > 3.0:
        raise ValueError("multiplicador deve estar entre 0.5 e 3.0")
    return int(round(pontuacao_base * multiplicador))

def classificar_triangulo(a, b, c):
    if a <= 0 or b <= 0 or c <= 0:
        raise ValueError("Lados devem ser positivos")
    if a + b <= c or a + c <= b or b + c <= a:
        raise ValueError("Desigualdade triangular violada")
    if a == b == c:
        return "equilátero"
    elif a == b or a == c or b == c:
        return "isósceles"
    else:
        return "escaleno"

