class Estoque:
    def __init__(self, produtos_iniciais=None):
        self._produtos = {}
        if produtos_iniciais:
            for nome, qtd in produtos_iniciais.items():
                if not isinstance(qtd, int) or qtd < 0:
                    raise ValueError("Quantidade inicial deve ser inteiro não negativo")
                if qtd > 0:
                    self._produtos[nome] = qtd

    def adicionar(self, nome, quantidade):
        if not isinstance(quantidade, int) or quantidade <= 0:
            raise ValueError("Quantidade para adicionar deve ser inteiro positivo")
        self._produtos[nome] = self._produtos.get(nome, 0) + quantidade

    def remover(self, nome, quantidade):
        if not isinstance(quantidade, int) or quantidade <= 0:
            raise ValueError("Quantidade para remover deve ser inteiro positivo")
        atual = self._produtos.get(nome, 0)
        if quantidade > atual:
            raise ValueError("Quantidade insuficiente em estoque")
        novo = atual - quantidade
        if novo:
            self._produtos[nome] = novo
        else:
            self._produtos.pop(nome, None)

    def consultar(self, nome):
        return self._produtos.get(nome, 0)

    def listar_produtos(self):
        return sorted((nome, qtd) for nome, qtd in self._produtos.items() if qtd > 0)

class CalculadoraJuros:
    def __init__(self, taxa_anual: float):
        self.taxa_anual = taxa_anual

    def calcular_juros_simples(self, capital: float, tempo_anos: float) -> float:
        if capital < 0 or tempo_anos < 0:
            raise ValueError("Capital e tempo devem ser não-negativos")
        return capital * self.taxa_anual * tempo_anos

    def calcular_montante_composto(self, capital: float, tempo_anos: float) -> float:
        if capital < 0 or tempo_anos < 0:
            raise ValueError("Capital e tempo devem ser não-negativos")
        return capital * (1 + self.taxa_anual) ** tempo_anos

def construir_histograma(iteravel, ordenar=False):
    try:
        iter(iteravel)
    except TypeError:
        raise TypeError("O argumento deve ser iterável")

    contagem = {}
    for item in iteravel:
        contagem[item] = contagem.get(item, 0) + 1

    if ordenar:
        return dict(sorted(contagem.items()))
    return contagem

