def extrair_iniciais(nome: str) -> str:
    if not isinstance(nome, str):
        raise TypeError("nome deve ser uma string")
    partes = nome.strip().split()
    if not partes:
        raise ValueError("nome não pode ser vazio ou apenas espaços")
    conectivos = {"de", "da", "do", "dos", "das", "e"}
    partes_validas = [p for p in partes if p.lower() not in conectivos]
    if not partes_validas:
        raise ValueError("nome não possui partes válidas após remover conectivos")
    iniciais = [p[0].upper() for p in partes_validas]
    return ". ".join(iniciais)

def agrupar_vendas_por_mes(lista_vendas):
    resultado = {}
    for data_str, valor in lista_vendas:
        if not isinstance(valor, (int, float)):
            raise ValueError("Valor deve ser numérico")
        partes = data_str.split("-")
        if len(partes) != 3:
            raise ValueError("Data deve estar no formato YYYY-MM-DD")
        ano, mes, dia = partes
        if not (ano.isdigit() and mes.isdigit() and dia.isdigit()):
            raise ValueError("Data deve conter apenas dígitos")
        if len(ano) != 4 or len(mes) != 2 or len(dia) != 2:
            raise ValueError("Data deve estar no formato YYYY-MM-DD")
        mes_int = int(mes)
        if not 1 <= mes_int <= 12:
            raise ValueError("Mês inválido")
        chave = f"{ano}-{mes}"
        resultado.setdefault(chave, []).append(valor)
    return resultado


def total_por_mes(lista_vendas):
    agrupado = agrupar_vendas_por_mes(lista_vendas)
    return {mes: sum(valores) for mes, valores in agrupado.items()}

