def numero_por_extenso(n: int) -> str:
    if not isinstance(n, int) or n < 0 or n > 99:
        raise ValueError("número fora do intervalo suportado")
    if n < 10:
        return UNIDADES[n]
    if n in DEZENAS_ESPECIAIS:
        return DEZENAS_ESPECIAIS[n]
    dezena, unidade = divmod(n, 10)
    if unidade == 0:
        return DEZENAS_REGULARES[dezena]
    return f"{DEZENAS_REGULARES[dezena]} e {UNIDADES[unidade]}"

def classificar_status(codigo: int) -> str:
    if not isinstance(codigo, int):
        raise ValueError("Código deve ser um inteiro")
    if codigo < 100 or codigo > 599:
        raise ValueError("Código HTTP deve estar entre 100 e 599")

    if 100 <= codigo <= 199:
        return "Informational"
    elif 200 <= codigo <= 299:
        return "Successful"
    elif 300 <= codigo <= 399:
        return "Redirection"
    elif 400 <= codigo <= 499:
        return "Client Error"
    else:
        return "Server Error"


