class DepreciacaoBem:
    def __init__(self, valor_inicial: float, vida_util_anos: int, metodo: str):
        if valor_inicial <= 0:
            raise ValueError("valor_inicial deve ser maior que zero")
        if vida_util_anos <= 0:
            raise ValueError("vida_util_anos deve ser maior que zero")
        if metodo not in ("linear", "soma_digitos", "saldo_declinante"):
            raise ValueError("metodo deve ser 'linear', 'soma_digitos' ou 'saldo_declinante'")

        self.valor_inicial = valor_inicial
        self.vida_util_anos = vida_util_anos
        self.metodo = metodo
        self._soma_digitos = vida_util_anos * (vida_util_anos + 1) // 2

    def calcular_depreciacao(self, ano: int) -> float:
        if ano <= 0 or ano > self.vida_util_anos:
            raise ValueError("ano deve estar entre 1 e vida_util_anos")

        if self.metodo == "linear":
            return self.valor_inicial / self.vida_util_anos

        elif self.metodo == "soma_digitos":
            fracao = (self.vida_util_anos - ano + 1) / self._soma_digitos
            return self.valor_inicial * fracao

        else:  # saldo_declinante
            taxa = 2.0 / self.vida_util_anos
            valor_residual_anterior = self.valor_residual(ano - 1) if ano > 1 else self.valor_inicial
            depreciacao = valor_residual_anterior * taxa
            return min(depreciacao, valor_residual_anterior)

    def valor_residual(self, ano: int) -> float:
        if ano <= 0 or ano > self.vida_util_anos:
            raise ValueError("ano deve estar entre 1 e vida_util_anos")

        if self.metodo == "linear":
            depreciacao_acumulada = (self.valor_inicial / self.vida_util_anos) * ano
            return self.valor_inicial - depreciacao_acumulada

        elif self.metodo == "soma_digitos":
            depreciacao_acumulada = 0.0
            for a in range(1, ano + 1):
                fracao = (self.vida_util_anos - a + 1) / self._soma_digitos
                depreciacao_acumulada += self.valor_inicial * fracao
            return self.valor_inicial - depreciacao_acumulada

        else:  # saldo_declinante
            if ano == 1:
                valor_residual_anterior = self.valor_inicial
            else:
                valor_residual_anterior = self.valor_residual(ano - 1)
            taxa = 2.0 / self.vida_util_anos
            depreciacao = valor_residual_anterior * taxa
            depreciacao = min(depreciacao, valor_residual_anterior)
            return valor_residual_anterior - depreciacao

class FilaMensagens:
    def __init__(self):
        self._fila = []
        self._proximo_id = 1
        self._confirmados = set()

    def enfileirar(self, msg):
        msg_id = self._proximo_id
        self._proximo_id += 1
        self._fila.append((msg_id, msg))
        return msg_id

    def desenfileirar(self):
        if not self._fila:
            raise IndexError("Fila vazia")
        msg_id, msg = self._fila.pop(0)
        return (msg_id, msg)

    def confirmar(self, msg_id):
        if msg_id in self._confirmados:
            raise ValueError("ID já confirmado")
        for i, (mid, _) in enumerate(self._fila):
            if mid == msg_id:
                self._confirmados.add(msg_id)
                self._fila.pop(i)
                return
        raise ValueError("ID não encontrado")

    def pendentes(self):
        return list(self._fila)

class AnaliseCabecalhosHTTP:
    def __init__(self):
        self._headers = {}

    def _validar_nome(self, nome: str) -> None:
        if not nome:
            raise ValueError("Nome do cabeçalho não pode ser vazio")
        for ch in nome:
            code = ord(ch)
            if code <= 31 or code >= 127 or ch in '()<>@,;:\\"/[]?={} \t':
                raise ValueError(f"Caractere inválido no nome do cabeçalho: {repr(ch)}")

    def _validar_valor(self, valor: str) -> None:
        for ch in valor:
            code = ord(ch)
            if code <= 31 and ch != '\t':
                raise ValueError(f"Caractere de controle inválido no valor: {repr(ch)}")
            if code == 127:
                raise ValueError(f"Caractere DEL inválido no valor: {repr(ch)}")

    def adicionar(self, nome: str, valor: str) -> None:
        self._validar_nome(nome)
        self._validar_valor(valor)
        nome_lower = nome.lower()
        if nome_lower not in self._headers:
            self._headers[nome_lower] = []
        self._headers[nome_lower].append(valor)

    def remover(self, nome: str) -> None:
        self._validar_nome(nome)
        nome_lower = nome.lower()
        if nome_lower in self._headers:
            del self._headers[nome_lower]

    def obter_valores(self, nome: str) -> list[str]:
        self._validar_nome(nome)
        nome_lower = nome.lower()
        return list(self._headers.get(nome_lower, []))

    def existe(self, nome: str) -> bool:
        self._validar_nome(nome)
        nome_lower = nome.lower()
        return nome_lower in self._headers

    def limpar(self) -> None:
        self._headers.clear()

import heapq
from typing import Any, Optional


class FilaPrioridade:
    def __init__(self):
        self._heap = []
        self._contador = 0

    def adicionar(self, item: Any, prioridade: int) -> None:
        if not isinstance(prioridade, int):
            raise TypeError("Prioridade deve ser um inteiro")
        heapq.heappush(self._heap, (prioridade, self._contador, item))
        self._contador += 1

    def remover(self) -> Any:
        if not self._heap:
            raise IndexError("Fila vazia")
        _, _, item = heapq.heappop(self._heap)
        return item

    def consultar(self) -> Optional[Any]:
        if not self._heap:
            return None
        return self._heap[0][2]

    def __len__(self) -> int:
        return len(self._heap)

    def __bool__(self) -> bool:
        return bool(self._heap)

def extrair_campos(template: str) -> list[str]:
    if not isinstance(template, str):
        raise ValueError("Template deve ser uma string")

    campos = []
    i = 0
    profundidade = 0
    inicio_campo = -1

    while i < len(template):
        if i + 1 < len(template) and template[i] == '{' and template[i+1] == '{':
            if profundidade == 0:
                inicio_campo = i + 2
            profundidade += 1
            i += 2
        elif i + 1 < len(template) and template[i] == '}' and template[i+1] == '}':
            if profundidade == 0:
                raise ValueError("Chaves desbalanceadas no template")
            profundidade -= 1
            if profundidade == 0:
                nome_campo = template[inicio_campo:i].strip()
                if nome_campo:
                    campos.append(nome_campo)
                inicio_campo = -1
            i += 2
        else:
            i += 1

    if profundidade != 0:
        raise ValueError("Chaves desbalanceadas no template")

    return sorted(set(campos))


def renderizar_template(template: str, contexto: dict) -> str:
    if not isinstance(template, str):
        raise ValueError("Template deve ser uma string")
    if not isinstance(contexto, dict):
        raise ValueError("Contexto deve ser um dicionário")

    resultado = []
    i = 0
    profundidade = 0
    inicio_campo = -1

    while i < len(template):
        if i + 1 < len(template) and template[i] == '{' and template[i+1] == '{':
            if profundidade == 0:
                inicio_campo = i + 2
            profundidade += 1
            i += 2
        elif i + 1 < len(template) and template[i] == '}' and template[i+1] == '}':
            if profundidade == 0:
                raise ValueError("Chaves desbalanceadas no template")
            profundidade -= 1
            if profundidade == 0:
                nome_campo = template[inicio_campo:i].strip()
                if nome_campo and nome_campo in contexto:
                    resultado.append(str(contexto[nome_campo]))
                else:
                    resultado.append(template[inicio_campo-2:i+2])
                inicio_campo = -1
            i += 2
        else:
            if profundidade == 0:
                resultado.append(template[i])
            i += 1

    if profundidade != 0:
        raise ValueError("Chaves desbalanceadas no template")

    return ''.join(resultado)

def rotacionar_esquerda(lista, k):
    if k < 0:
        raise ValueError("k deve ser não-negativo")
    n = len(lista)
    if n == 0:
        return []
    k = k % n
    return lista[k:] + lista[:k]


def rotacionar_direita(lista, k):
    if k < 0:
        raise ValueError("k deve ser não-negativo")
    n = len(lista)
    if n == 0:
        return []
    k = k % n
    return lista[-k:] + lista[:-k]

from datetime import date, timedelta


def calcular_prazo_entrega(data_inicio: str, dias_uteis: int) -> str:
    if dias_uteis < 0:
        raise ValueError("Dias úteis não pode ser negativo")
    try:
        data = date.fromisoformat(data_inicio)
    except ValueError:
        raise ValueError("Data inválida ou formato incorreto")
    adicionados = 0
    while adicionados < dias_uteis:
        data += timedelta(days=1)
        if data.weekday() < 5:
            adicionados += 1
    return data.isoformat()

