        raise ValueError("Campo 'tipo' deve ser string")

    allowed_types = {"image/png", "image/jpeg", "application/pdf", "text/plain"}
    max_size = 5_000_000

    return metadata["tamanho"] <= max_size and metadata["tipo"] in allowed_types


