class PlacarBasquete:
    """Gerencia o placar de uma partida de basquete entre dois times."""

    def __init__(self):
        self._pontos = {'A': 0, 'B': 0}

    def registrar_cesta(self, time: str, pontos: int) -> None:
        """Registra uma cesta para o time informado.

        Args:
            time: Identificador do time ('A' ou 'B').
            pontos: Valor da cesta (1, 2 ou 3).

        Raises:
            ValueError: Se time não for 'A' nem 'B' ou pontos não for 1, 2 ou 3.
        """
        if time not in ('A', 'B'):
            raise ValueError("Time inválido. Use 'A' ou 'B'.")
        if pontos not in (1, 2, 3):
            raise ValueError("Pontos inválidos. Use 1, 2 ou 3.")
        self._pontos[time] += pontos

    def consultar_placar(self) -> dict:
        """Retorna uma cópia do placar atual."""
        return self._pontos.copy()

    def reiniciar(self) -> None:
        """Zera a pontuação de ambos os times."""
        self._pontos['A'] = 0
        self._pontos['B'] = 0

    def vencedor(self) -> str:
        """Retorna 'A', 'B' ou 'Empate' conforme a pontuação atual."""
        if self._pontos['A'] > self._pontos['B']:
            return 'A'
        if self._pontos['B'] > self._pontos['A']:
            return 'B'
        return 'Empate'

def calcular_nivel_experiencia(experiencia: int) -> tuple[int, int]:
    if experiencia < 0:
        raise ValueError("Experiência não pode ser negativa")

    nivel = 1
    xp_necessario_proximo = 100
    xp_acumulado = 0

    while True:
        if experiencia < xp_acumulado + xp_necessario_proximo:
            xp_para_proximo = (xp_acumulado + xp_necessario_proximo) - experiencia
            return (nivel, xp_para_proximo)

        xp_acumulado += xp_necessario_proximo
        nivel += 1
