    linhas = []
    for reg in registros:
        if not isinstance(reg, dict):
            raise TypeError("Cada registro deve ser um dicionário")
        campos = []
        for chave, valor in reg.items():
            if not isinstance(chave, str):
                raise TypeError("Chaves devem ser strings")
            if valor is None:
                campos.append("NULL")
            elif isinstance(valor, bool):
                campos.append("true" if valor else "false")
            elif isinstance(valor, (int, float)):
                campos.append(str(valor))
            elif isinstance(valor, str):
                escapado = valor.replace('"', '""')
                campos.append(f'"{escapado}"')
