class VersionamentoConfig:
    def __init__(self, config_inicial: dict):
        self._versoes = {1: dict(config_inicial)}
        self._versao_atual = 1

    def atualizar(self, novas_configs: dict) -> int:
        self._versao_atual += 1
        config_anterior = self._versoes[self._versao_atual - 1]
        nova_config = dict(config_anterior)
        nova_config.update(novas_configs)
        self._versoes[self._versao_atual] = nova_config
        return self._versao_atual

    def obter(self, versao: int) -> dict:
        if versao <= 0 or versao > self._versao_atual:
            raise ValueError("Versão inválida")
        return dict(self._versoes[versao])

    def diff(self, versao_a: int, versao_b: int) -> dict:
        if versao_a <= 0 or versao_a > self._versao_atual:
            raise ValueError("Versão A inválida")
        if versao_b <= 0 or versao_b > self._versao_atual:
            raise ValueError("Versão B inválida")
        config_a = self._versoes[versao_a]
        config_b = self._versoes[versao_b]
        chaves_a = set(config_a.keys())
        chaves_b = set(config_b.keys())
        adicionadas = chaves_b - chaves_a
        removidas = chaves_a - chaves_b
        comuns = chaves_a & chaves_b
        alteradas = {}
        inalteradas = {}
        for k in comuns:
            if config_a[k] != config_b[k]:
                alteradas[k] = (config_a[k], config_b[k])
            else:
                inalteradas[k] = config_a[k]
        return {
            'adicionadas': {k: config_b[k] for k in adicionadas},
            'removidas': {k: config_a[k] for k in removidas},
            'alteradas': alteradas,
            'inalteradas': inalteradas
        }

