def divisores_primos(n):
    if n < 2:
        raise ValueError("n deve ser maior ou igual a 2")
    primos = []
    d = 2
    temp = n
    while d * d <= temp:
        if temp % d == 0:
            primos.append(d)
            while temp % d == 0:
                temp //= d
        d += 1
    if temp > 1:
        primos.append(temp)
    return primos

