def para_moeda(valor):
    if isinstance(valor, bool) or not isinstance(valor, (int, float)):
        raise ValueError("valor deve ser um número")
    if valor < 0:
        raise ValueError("valor não pode ser negativo")
    arredondado = round(valor, 2)
    inteiro = int(arredondado)
    centavos = int(round((arredondado - inteiro) * 100))
    if centavos == 100:
        inteiro += 1
        centavos = 0
    partes = []
    if inteiro == 0:
        partes.append("0")
    else:
        while inteiro > 0:
            partes.append(str(inteiro % 1000).zfill(3) if inteiro >= 1000 else str(inteiro % 1000))
            inteiro //= 1000
    inteiro_formatado = ".".join(reversed(partes))
    return "R$ {},{:02d}".format(inteiro_formatado, centavos)


def extrair_valor(texto):
    if not isinstance(texto, str):
        raise ValueError("texto deve ser uma string")
    texto = texto.strip()
    if not texto.startswith("R$ "):
        raise ValueError("texto deve começar com 'R$ '")
    corpo = texto[3:]
    if "," not in corpo:
        raise ValueError("texto deve conter vírgula decimal")
    parte_inteira, parte_decimal = corpo.rsplit(",", 1)
    if len(parte_decimal) != 2 or not parte_decimal.isdigit():
        raise ValueError("texto deve ter exatamente duas casas decimais")
    if parte_inteira == "":
        raise ValueError("parte inteira não pode estar vazia")
    blocos = parte_inteira.split(".")
    if len(blocos[0]) == 0 or len(blocos[0]) > 3 or not blocos[0].isdigit():
        raise ValueError("primeiro bloco inválido")
    for bloco in blocos[1:]:
        if len(bloco) != 3 or not bloco.isdigit():
            raise ValueError("blocos de milhares devem ter exatamente três dígitos")
    inteiro_str = "".join(blocos)
    return float(inteiro_str + "." + parte_decimal)

