class ConversorNumeralRomano:
    _VALORES = [
        (1000, "M"),
        (900, "CM"),
        (500, "D"),
        (400, "CD"),
        (100, "C"),
        (90, "XC"),
        (50, "L"),
        (40, "XL"),
        (10, "X"),
        (9, "IX"),
        (5, "V"),
        (4, "IV"),
        (1, "I"),
    ]

    _ROMANO_PARA_INTEIRO = {
        "I": 1,
        "V": 5,
        "X": 10,
        "L": 50,
        "C": 100,
        "D": 500,
        "M": 1000,
    }

    def __init__(self):
        self.ultimo_valor = None

    def para_romano(self, numero):
        if isinstance(numero, bool) or not isinstance(numero, int):
            raise ValueError("numero deve ser inteiro")
        if numero < 1 or numero > 3999:
            raise ValueError("numero deve estar entre 1 e 3999")
        resultado = ""
        restante = numero
        for valor, simbolo in self._VALORES:
            while restante >= valor:
                resultado += simbolo
                restante -= valor
        self.ultimo_valor = numero
        return resultado

    def _eh_romano_valido(self, texto):
        if not texto:
            return False
        for caractere in texto:
            if caractere not in self._ROMANO_PARA_INTEIRO:
                return False
        for repetido in ("V", "L", "D"):
            if texto.count(repetido) > 1:
                return False
        for simbolo in ("I", "X", "C", "M"):
            if simbolo * 4 in texto:
                return False
        pares_subtrativos = {"IV", "IX", "XL", "XC", "CD", "CM"}
        for indice in range(len(texto) - 1):
            atual = texto[indice]
            seguinte = texto[indice + 1]
            if self._ROMANO_PARA_INTEIRO[atual] < self._ROMANO_PARA_INTEIRO[seguinte]:
                par = atual + seguinte
                if par not in pares_subtrativos:
                    return False
                if indice > 0 and texto[indice - 1] == atual:
                    return False
                if indice + 2 < len(texto) and self._ROMANO_PARA_INTEIRO[texto[indice + 2]] > self._ROMANO_PARA_INTEIRO[atual]:
                    return False
        return True

    def de_romano(self, texto):
        if not isinstance(texto, str):
            raise ValueError("texto deve ser string")
        if not self._eh_romano_valido(texto):
            raise ValueError("texto nao e um numeral romano valido")
        total = 0
        indice = 0
        while indice < len(texto):
            valor_atual = self._ROMANO_PARA_INTEIRO[texto[indice]]
            if indice + 1 < len(texto):
                valor_seguinte = self._ROMANO_PARA_INTEIRO[texto[indice + 1]]
                if valor_atual < valor_seguinte:
                    total += valor_seguinte - valor_atual
                    indice += 2
                    continue
            total += valor_atual
            indice += 1
        self.ultimo_valor = total
        return total

