def calcular_pagamento(salario_base, horas_extras):
    if salario_base < 0:
        raise ValueError("Salário base não pode ser negativo")
    if horas_extras < 0:
        raise ValueError("Horas extras não podem ser negativas")

    valor_hora = salario_base / 220
    if horas_extras <= 10:
        valor_extras = horas_extras * valor_hora * 1.5
