        self._registros = []

    def adicionar(self, item, chaves):
        if not chaves:
            raise ValueError("item deve ter pelo menos uma chave")
        self._registros.append((item, list(chaves)))

    def classificar(self):
        if not self._registros:
            raise ValueError("nenhum item foi adicionado")
        resultado = list(self._registros)
        for indice in range(len(resultado[0][1]) - 1, -1, -1):
