def validar_dependencias(servicos):
    nomes = set(servicos.keys())
    for servico, dependencias in servicos.items():
        for dep in dependencias:
            if dep not in nomes:
                raise ValueError("serviço dependente ausente: " + str(dep))
    visitando = set()
    visitados = set()
    def visitar(servico):
        if servico in visitados:
            return
        if servico in visitando:
            raise ValueError("ciclo detectado envolvendo " + str(servico))
        visitando.add(servico)
        for dep in servicos[servico]:
            visitar(dep)
        visitando.remove(servico)
        visitados.add(servico)
    for servico in servicos:
        visitar(servico)


def ordenar_servicos(servicos):
    validar_dependencias(servicos)
    nomes = set(servicos.keys())
    grau_entrada = {servico: 0 for servico in servicos}
    dependentes = {servico: [] for servico in servicos}
    for servico, dependencias in servicos.items():
        for dep in dependencias:
            dependentes[dep].append(servico)
            grau_entrada[servico] += 1
    fila = sorted([s for s in servicos if grau_entrada[s] == 0])
    ordem = []
    while fila:
        atual = fila.pop(0)
        ordem.append(atual)
        for dep in dependentes[atual]:
            grau_entrada[dep] -= 1
            if grau_entrada[dep] == 0:
                fila.append(dep)
        fila.sort()
    return ordem

