def disparar_tiros(tiros, navios):
    for tiro in tiros:
        if not isinstance(tiro, tuple) or len(tiro) != 2 or not all(isinstance(x, int) for x in tiro):
            raise ValueError("coordenadas inválidas")
    for navio in navios:
        if not isinstance(navio, tuple) or len(navio) != 2 or not all(isinstance(x, int) for x in navio):
            raise ValueError("coordenadas inválidas")
    acertados = set()
    errados = set()
    navios_set = set(navios)
    for tiro in tiros:
        if tiro in acertados or tiro in errados:
            continue
        if tiro in navios_set:
            acertados.add(tiro)
