def contar_ilhas(matriz):
    if not matriz:
        return 0
    linhas = len(matriz)
    colunas = len(matriz[0])
    visitado = [[False] * colunas for _ in range(linhas)]
    total = 0
    for i in range(linhas):
        for j in range(colunas):
            if matriz[i][j] == 1 and not visitado[i][j]:
                total += 1
                pilha = [(i, j)]
                visitado[i][j] = True
                while pilha:
                    x, y = pilha.pop()
                    for dx, dy in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                        nx, ny = x + dx, y + dy
                        if 0 <= nx < linhas and 0 <= ny < colunas:
                            if matriz[nx][ny] == 1 and not visitado[nx][ny]:
                                visitado[nx][ny] = True
                                pilha.append((nx, ny))
    return total


