def contar_por_faixa(registros, tamanho):
    if tamanho <= 0:
        raise ValueError("tamanho deve ser positivo")
    if not registros:
        return []
    for m in registros:
        if m < 0:
            raise ValueError("minuto negativo")
    maior = max(registros)
    resultado = []
    inicio = 0
    while inicio <= maior:
        fim = inicio + tamanho - 1
        qtd = sum(1 for m in registros if inicio <= m <= fim)
        resultado.append((inicio, fim, qtd))
        inicio += tamanho
    return resultado

