class ArvoreBinariaBusca:
    def __init__(self):
        self.raiz = None

    def _validar(self, valor):
        if not isinstance(valor, int) or isinstance(valor, bool):
            raise TypeError("valor deve ser inteiro")
        if valor < 0:
            raise ValueError("valor nao pode ser negativo")

    def inserir(self, valor):
        self._validar(valor)
        if self.raiz is None:
            self.raiz = {"valor": valor, "esq": None, "dir": None}
            return
        atual = self.raiz
        while True:
            if valor == atual["valor"]:
                return
            if valor < atual["valor"]:
                if atual["esq"] is None:
                    atual["esq"] = {"valor": valor, "esq": None, "dir": None}
                    return
                atual = atual["esq"]
            else:
                if atual["dir"] is None:
                    atual["dir"] = {"valor": valor, "esq": None, "dir": None}
                    return
                atual = atual["dir"]

    def buscar(self, valor):
        self._validar(valor)
        atual = self.raiz
        while atual is not None:
            if valor == atual["valor"]:
                return True
            atual = atual["esq"] if valor < atual["valor"] else atual["dir"]
        return False

    def em_ordem(self):
        resultado = []
        pilha = []
        atual = self.raiz
        while pilha or atual is not None:
            while atual is not None:
                pilha.append(atual)
                atual = atual["esq"]
            atual = pilha.pop()
            resultado.append(atual["valor"])
            atual = atual["dir"]
        return resultado

class No:
