        if not isinstance(antigas, list) or not all(isinstance(x, str) for x in antigas):
            raise ValueError("antigas deve ser lista de textos")
        self.antigas = antigas

    def _validar(self, novas):
        if not isinstance(novas, list) or not all(isinstance(x, str) for x in novas):
            raise ValueError("novas deve ser lista de textos")

    def acrescentadas(self, novas):
        self._validar(novas)
        antigo = set(self.antigas)
        return sorted({x for x in novas if x not in antigo})

    def removidas(self, novas):
        self._validar(novas)
        novo = set(novas)
        return sorted({x for x in self.antigas if x not in novo})

    def mantidas(self, novas):
        self._validar(novas)
        novo = set(novas)
        return sorted({x for x in self.antigas if x in novo})
